<template>
  <div><RemoteFeedback :message="error" /><RemoteAction v-if="unresolved" icon="alert" tone="danger" @click="$emit('pending')">发送结果待核对</RemoteAction>
    <template v-if="!current"><div class="remote-purpose-actions"><RemoteAction icon="plus" tone="primary" :disabled="busy || unresolved" @click="configure('create')">新房间</RemoteAction><RemoteAction icon="refresh" tone="quiet" :disabled="busy" @click="run(load)">刷新</RemoteAction></div><div class="remote-prompt-list"><button v-for="room in rooms" :key="room.id" :disabled="busy" @click="enter(room)"><RemoteIcon name="home" /><span><strong>{{ room.name }}</strong><small>{{ room.description || '进入群聊' }} · {{ room.agents?.length || 0 }} 位角色</small></span><RemoteIcon name="next" /></button></div><p v-if="!rooms.length && !busy" class="room-empty">还没有房间，先创建一个吧。</p><details class="remote-secondary-operations"><summary><RemoteIcon name="settings" />设施与管家</summary><div class="remote-purpose-actions"><RemoteAction icon="plus" :disabled="busy || unresolved" @click="configure('facility')">创建设施</RemoteAction><RemoteAction icon="settings" :disabled="busy || unresolved" @click="configure('butler')">管家设置</RemoteAction></div></details></template>
    <template v-if="current"><header class="remote-record-heading"><RemoteAction icon="back" tone="quiet" :disabled="busy" @click="exitRoom">房间列表</RemoteAction><div><small>群聊房间</small><h2>{{ current.name }}</h2></div><button class="room-icon-button" aria-label="刷新房间消息" :disabled="busy" @click="run(loadRoom)"><RemoteIcon name="refresh" /></button></header><div class="remote-room-members"><span v-for="member in projection?.members || []" :key="member.agentId"><RemoteAvatar :id="member.agentId" :label="agentName(member.agentId)" />{{ agentName(member.agentId) }}</span></div>
      <details class="remote-secondary-operations"><summary><RemoteIcon name="settings" />房间资料与管理</summary><p v-if="current.description" class="remote-help">{{ current.description }}</p><RemoteRecordView kind="rooms" :record="current" /><div class="remote-purpose-actions"><RemoteAction icon="edit" :disabled="busy || unresolved" @click="configure('edit')">编辑资料</RemoteAction><RemoteAction icon="profile" :disabled="busy || unresolved" @click="configure('member')">邀请 / 移动角色</RemoteAction><RemoteAction icon="home" :disabled="busy || unresolved" @click="configure('environment')">调整环境</RemoteAction><RemoteAction icon="send" :disabled="busy || unresolved" @click="configure('command')">管家指令</RemoteAction></div><RemoteAction icon="trash" tone="danger" :disabled="busy || unresolved" @click="configure('delete')">删除房间</RemoteAction></details>
      <div class="remote-room-history"><article v-for="surface in projection?.surfaces || []" :key="surface.surfaceId" class="remote-message"><div class="remote-message-label"><span>{{ sender(surface.messageId) }}</span><button v-if="surface.messageId" class="remote-message-tools" aria-label="删除此轮群聊" :disabled="busy || unresolved" @click="deleting = String(surface.messageId); operation = 'delete_message'; form = {}; formBaseline = '{}' "><RemoteIcon name="trash" /></button></div><RemoteSurface :surface="surface" :disabled="remoteState.connection !== 'online'" @resource="$emit('resource', $event)" @updated="run(loadRoom)" /></article><p v-if="!projection?.surfaces?.length" class="room-empty">这里还没有消息</p></div>
      <form class="remote-manager-card" @submit.prevent="send"><label class="remote-field"><span>提及角色</span><RemoteSelect v-model="mention" label="提及角色" :options="mentionOptions" :disabled="busy" /></label><label class="remote-field"><span>群聊消息</span><textarea v-model="message" rows="3" maxlength="16000" required /></label><RemoteAction icon="send" tone="primary" type="submit" :disabled="busy || unresolved || !message.trim()">发送到房间</RemoteAction></form>
    </template>
    <RoomDrawer v-if="operation" :title="titles[operation]" :busy="busy" :before-close="beforeCloseOperation" @close="operation = null"><RemoteFeedback :message="error" /><p v-if="operation === 'delete' || operation === 'delete_message'" class="remote-operation-scope">{{ operation === 'delete' ? '确认删除此房间及其聊天记录？' : '按 infOS 群聊规则删除此轮用户发言及关联回复。' }}</p><form @submit.prevent="submit"><RemoteFormSections v-model="form" kind="rooms" :fields="fields" :disabled="busy" /><RemoteAction :icon="operation.startsWith('delete') ? 'trash' : 'check'" :tone="operation.startsWith('delete') ? 'danger' : 'primary'" type="submit" :disabled="busy || unresolved">{{ operation.startsWith('delete') ? '确认删除' : '保存到 infOS' }}</RemoteAction></form></RoomDrawer>
    <RoomDrawer v-if="discardOperation" title="放弃本次修改？" @close="discardOperation = false"><p>房间设置还没有保存。</p><RemoteAction icon="close" tone="danger" @click="operation = null; discardOperation = false">放弃修改</RemoteAction></RoomDrawer>
  </div>
</template>
<script setup>
import RemoteFeedback from './RemoteFeedback.vue'
import { ref, computed, onMounted, onBeforeUnmount } from 'vue'
import { useRemoteManagement } from '../../composables/useRemoteManagement'
import { field, inferFields } from '../../services/remoteManagement'
import { remoteState } from '../../stores/remote'
import RemoteIcon from './RemoteIcon.vue'
import RemoteFormSections from './RemoteFormSections.vue'
import RemoteRecordView from './RemoteRecordView.vue'
import RemoteAvatar from './RemoteAvatar.vue'
import RemoteAction from './RemoteAction.vue'
import RemoteSurface from './RemoteSurface.vue'
import RemoteSelect from './RemoteSelect.vue'

import RoomDrawer from '../companion/RoomDrawer.vue'
const props = defineProps({ agentId: String })
defineEmits(['pending', 'resource'])
const { read, write, run, busy, error, unresolved } = useRemoteManagement()
const rooms = ref([]), facilities = ref([]), current = ref(null), projection = ref(null), message = ref(''), mention = ref(''), operation = ref(null), form = ref({}), deleting = ref('')
const titles = { facility: '创建设施', create: '创建房间', edit: '房间资料', member: '移动角色到此房间', environment: '更新环境变量', command: '管家指令', butler: '管家设置', delete: '删除房间', delete_message: '删除这轮群聊？' }
const fields = computed(() => operation.value === 'create' ? [field('facilityId', 'number', { choices: facilities.value.map(item => ({ value: item.id, label: item.name })) }), field('name'), field('description', 'long')] : operation.value === 'member' ? [field('agentId', 'text', { choices: remoteState.agents.filter(item => item.isEnabled !== false && !item.isUser).map(item => ({ value: item.id, label: item.name })) })] : inferFields(form.value))
const mentionOptions = computed(() => [{ value: '', label: '自动选择' }, { value: '@all', label: '全体成员' }, ...(projection.value?.members || []).map(member => ({ value: member.agentId, label: agentName(member.agentId) }))])
const formBaseline = ref('{}'), discardOperation = ref(false)
const hasChanges = computed(() => !!message.value.trim() || !!operation.value && JSON.stringify(form.value) !== formBaseline.value)
function exitRoom() { if (message.value.trim()) { error.value = '请先发送或清空当前群聊输入'; return }; current.value = null; projection.value = null }
function beforeCloseOperation() { if (JSON.stringify(form.value) !== formBaseline.value) { discardOperation.value = true; return false } return true }
defineExpose({ busy, hasChanges })
let timer = null, disposed = false, polling = false
function agentName(id) { return remoteState.agents.find(item => item.id === id)?.name || id }
function sender(messageId) { const message = projection.value?.messages?.find(item => item.messageId === String(messageId)); return message?.role === 'user' ? '你' : agentName(message?.senderId || '') }
async function load() { const values = await Promise.all([read('rooms.list'), read('facilities.list')]); rooms.value = values[0]; facilities.value = values[1]; if (current.value) { current.value = rooms.value.find(item => item.id === current.value.id) || null; if (current.value) await loadRoom(); else projection.value = null } }
async function loadRoom() { if (!current.value) return; const id = current.value.id; const value = await read('rooms.projection', { id, params: { limit: 100 } }); if (current.value?.id === id) projection.value = value }
async function enter(room) { await run(async () => { if (message.value.trim()) throw new Error('请先发送或清空当前群聊输入'); projection.value = null; current.value = room; await loadRoom() }) }
async function configure(op) { await run(async () => { if (op === 'butler') { const value = await read('butler.get'); form.value = { enabled: !!value.enabled } } else form.value = op === 'facility' ? { name: '', description: '' } : op === 'create' ? { facilityId: facilities.value[0]?.id ?? 0, name: '', description: '' } : op === 'edit' ? { name: current.value.name, description: current.value.description || '' } : op === 'member' ? { agentId: props.agentId || '' } : op === 'environment' ? { key: '', value: '' } : op === 'command' ? { command: '' } : {}; formBaseline.value = JSON.stringify(form.value); operation.value = op }) }
async function submit() { await run(async () => { const op = operation.value, map = { facility: 'facilities.create', create: 'rooms.create', edit: 'rooms.save', member: 'rooms.move', environment: 'rooms.environment', command: 'rooms.butler', butler: 'butler.save', delete: 'rooms.delete', delete_message: 'rooms.delete_message' }; const body = { ...form.value }; if (op === 'member') body.roomId = current.value.id; await write(map[op], { id: ['edit', 'environment', 'command', 'delete', 'delete_message'].includes(op) ? current.value.id : null, params: op === 'delete_message' ? { messageId: deleting.value } : {}, body: Object.keys(body).length ? body : null }); if (op === 'delete') { current.value = null; projection.value = null }; operation.value = null; await load() }) }
async function send() { await run(async () => { await write('rooms.message', { id: current.value.id, body: { content: message.value, senderId: 'user', role: 'user', mentions: mention.value ? [mention.value] : [] } }); message.value = ''; await loadRoom() }) }
async function poll() { if (disposed) return; if (!document.hidden && remoteState.connection === 'online' && current.value && !busy.value && !polling) { polling = true; try { await loadRoom() } catch (failure) { if (!disposed) error.value = failure.message } finally { polling = false } }; if (!disposed) timer = setTimeout(poll, 5000) }
onMounted(() => { run(load); poll() })
onBeforeUnmount(() => { disposed = true; clearTimeout(timer) })
</script>
